<template>
  <div class="satisfaction-chart-container" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <div class="satisfaction-header">
      <div class="satisfaction-filters">
        <button :class="['satisfaction-filter-btn', { active: selectedFilter === '30d' }]" @click="selectedFilter = '30d'">{{ $t('last30Days') }}</button>
        <button :class="['satisfaction-filter-btn', { active: selectedFilter === '3m' }]" @click="selectedFilter = '3m'">{{ $t('last3Months') }}</button>
      </div>
      <div class="satisfaction-title">{{ $t('customerSatisfactionRate') }}</div>
    </div>
    <div class="satisfaction-content">
      <div class="satisfaction-chart-graph-wrapper">
        <Doughnut :data="chartJsData" :options="chartOptions" class="satisfaction-chart-graph" />
      </div>
      <ul class="satisfaction-legend">
        <li class="satisfaction-legend-item" v-for="item in legendItems" :key="item.label">
          <span class="satisfaction-legend-color" :style="{ backgroundColor: item.color }"></span>
          {{ item.label }}
        </li>
      </ul>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { Doughnut } from 'vue-chartjs'
import {
  Chart as ChartJS,
  Title,
  Tooltip,
  Legend,
  ArcElement
} from 'chart.js'

ChartJS.register(Title, Tooltip, Legend, ArcElement)

const { t } = useI18n()
const selectedFilter = ref('30d')

// Data for each filter (example values)
const satisfactionData = computed(() => ({
  '30d': {
    labels: [t('verySatisfied'), t('satisfied'), t('neutral'), t('dissatisfied')],
    values: [40, 30, 15, 15],
  },
  '3m': {
    labels: [t('verySatisfied'), t('satisfied'), t('neutral'), t('dissatisfied')],
    values: [35, 32, 18, 15],
  }
}))

const satisfactionColors = ['#5B183D', '#000000', '#E5E5E5', '#BDBDBD']

const legendItems = computed(() => [
  { label: t('verySatisfied'), color: '#5B183D' },
  { label: t('satisfied'), color: '#000000' },
  { label: t('neutral'), color: '#E5E5E5' },
  { label: t('dissatisfied'), color: '#BDBDBD' },
])

const chartJsData = computed(() => ({
  labels: satisfactionData.value[selectedFilter.value].labels,
  datasets: [
    {
      data: satisfactionData.value[selectedFilter.value].values,
      backgroundColor: satisfactionColors,
      borderWidth: 4
    }
  ]
}))

const chartOptions = {
  cutout: '70%',
  plugins: {
    legend: { display: false },
    tooltip: { enabled: false },
    datalabels: { display: false },
  },
}
</script>

<style scoped>
.satisfaction-chart-container {
  background: #fff;
  padding: 1.5rem;
  border-radius: 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  width: 100%;
  box-sizing: border-box;
  
  @media (max-width: 768px) {
    padding: 1.2rem;
  }
  
  @media (max-width: 480px) {
    padding: 1rem;
  }
}
.satisfaction-header {
  display: flex;
  flex-direction: row-reverse;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}
.satisfaction-filters {
  display: flex;
  flex-direction: row-reverse;
  gap: 0.5rem;
}
.satisfaction-filter-btn {
  background: #f5f5f5;
  border: none;
  border-radius: 1rem;
  padding: 0.3rem 1.2rem;
  font-size: 0.95rem;
  color: #5B183D;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.satisfaction-filter-btn.active {
  background: #5B183D;
  color: #fff;
}
.satisfaction-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: #222;
  text-align: right;
}
.satisfaction-content {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}
.satisfaction-chart-graph-wrapper {
  width: 180px;
  min-width: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  
  @media (max-width: 768px) {
    width: 140px;
    min-width: 100px;
  }
  
  @media (max-width: 480px) {
    width: 120px;
    min-width: 80px;
  }
}
.satisfaction-chart-graph {
  width: 9rem !important;
  height: 9rem !important;
}
.satisfaction-legend {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  align-items: flex-start;
}
.satisfaction-legend-item {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
  font-size: 1rem;
  color: #333;
}
.satisfaction-legend-color {
  width: 1.2rem;
  height: 0.7rem;
  border-radius: 2px;
  display: inline-block;
}
@media (max-width: 768px) {
  .satisfaction-content {
    flex-direction: column-reverse;
    gap: 1.5rem;
    align-items: stretch;
  }
  .satisfaction-chart-graph-wrapper {
    margin: 0 auto;
  }
}
</style> 