<template>
  <div class="chart-container" :dir="$i18n.locale === 'ar' ? 'rtl' : 'ltr'">
    <!-- Header -->
    <div class="chart-header">
      <div class="tab-buttons">
        <button
          v-for="tab in tabs"
          :key="tab.key"
          @click="selectedTab = tab"
          :aria-pressed="selectedTab.key === tab.key"
          :class="[
            'tab-button',
            selectedTab.key === tab.key ? 'tab-button-active' : 'tab-button-inactive'
          ]"
        >
          {{ tab.label }}
        </button>
      </div>
      <h2 class="chart-title">
        {{ $t('dailyOrders') }}
      </h2>
    </div>
    <!-- Chart -->
    <div class="chart-wrapper">
      <Line :data="chartData" :options="chartOptions" class="chart" />
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { Line } from 'vue-chartjs'
import {
  Chart as ChartJS,
  Title,
  Legend,
  LineElement,
  LinearScale,
  PointElement,
  CategoryScale,
  Filler
} from 'chart.js'

// Register Chart.js modules
ChartJS.register(Title,  Legend, LineElement, LinearScale, PointElement, CategoryScale, Filler)

const { t } = useI18n()

const tabs = computed(() => [
  { key: t('yearly'), label: t('yearly') },
  { key: t('monthly'), label: t('monthly') },
  { key: t('weekly'), label: t('weekly') }
])

// Initialize selectedTab with a default value to prevent null reference errors
const selectedTab = ref({ key: t('monthly'), label: t('monthly') })

// Watch for changes in tabs and update selectedTab to keep it in sync
watch(tabs, (newTabs) => {
  // Find the monthly tab and set it as selected
  const monthlyTab = newTabs.find(tab => tab.key === t('monthly'))
  if (monthlyTab) {
    selectedTab.value = monthlyTab
  }
}, { immediate: true })

// Define datasets for each tab
const rawDatasets = {
  [t('weekly')]: {
    labels: [t('may18Short'), t('may19Short'), t('may20Short'), t('may21Short'), t('may22Short'), t('may23Short'), t('may25Short')],
    data: [100, 150, 120, 180, 130, 170, 140]
  },
  [t('monthly')]: {
    labels: [t('may18'), t('may19'), t('may20'), t('may21'), t('may22'), t('may23'), t('may25')],
    data: [180, 150, 200, 120, 190, 170, 160]
  },
  [t('yearly')]: {
    labels: ['2019', '2020', '2021', '2022', '2023'],
    data: [1500, 1600, 1800, 2000, 2200]
  }
}

// Create a gradient for the chart background
function getGradient(ctx, chartArea) {
  const gradient = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
  gradient.addColorStop(0.0912, 'rgba(208, 161, 185, 0.256)');
  gradient.addColorStop(0.9386, 'rgba(255, 255, 255, 0.8)');
  return gradient;
}

// Computed chart data based on selected tab
const chartData = computed(() => {
  const secondaryColor = '#5B183D'
  const current = rawDatasets[selectedTab.value?.key]
  if (!current) {
    return {
      labels: [],
      datasets: []
    }
  }

  return {
    labels: current.labels,
    datasets: [
      {
        label: '',
        data: current.data,
        fill: true,
        borderColor: secondaryColor,
        backgroundColor: (context) => {
          const { ctx, chartArea } = context.chart;
          if (!chartArea) return 'rgba(208, 161, 185, 0.256)'; // fallback
          return getGradient(ctx, chartArea);
        },
        tension: 0.4
      }
    ]
  }
})

// Chart options
const chartOptions = {
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    legend: { display: false },
    tooltip: { enabled: false },
    datalabels: {
      display: false, // Hide the data labels
    },
  },
  layout: {
    padding: {
      top: 20,
      right: 20,
      bottom: 10,
      left: 10
    }
  },
  scales: {
    x: {
      reverse: true,
      grid: { display: false },
      ticks: {
        font: { family: 'Inter, Arial', weight: 'bold', size: 8 },
        color: '#444'
      }
    },
    y: {
      display: true,
      grid: {
        color: 'rgba(200,200,200,0.15)',
        drawBorder: false
      },
      ticks: {
        font: { family: 'Inter, Arial', size: 8 },
        color: '#888',
        padding: 0
      }
    }
  },
}
</script>

<style scoped>
.chart-container {
  background-color: white;
  border-radius: 12px;
  padding: 0 0px;
  width: 100%;
  margin: 0 auto;
  box-sizing: border-box;
  
  @media (max-width: 768px) {
    padding: 0 10px;
  }
  
  @media (max-width: 480px) {
    padding: 0 8px;
  }
}

.chart-header {
  display: flex;
  flex-direction: row-reverse;
  justify-content: space-between;
  align-items: center;
  margin: 0px 0;
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: #1f2937;
  margin-right: 0;
}

.tab-buttons {
  display: flex;
  flex-direction: row-reverse;
  gap: 8px;
}

.tab-button {
  padding: 4px 12px;
  border-radius: 9999px;
  font-size: 14px;
  border: 1px solid;
  transition: all 0.2s ease;
  cursor: pointer;
}

.tab-button-active {
  background-color: #5B183D;
  color: white;
  border-color: #5B183D;
}

.tab-button-inactive {
  background-color: white;
  color: #374151;
  border-color: #d1d5db;
}

.tab-button-inactive:hover {
  background-color: #f3f4f6;
}

.chart-wrapper {
  min-height: 0;
  position: relative;
  width: 100%;
  
  @media (max-width: 768px) {
    min-height: 140px;
  }
  
  @media (max-width: 480px) {
    min-height: 120px;
  }
}

.chart {
  width: 100% !important;
  height: 200px !important;
  
  @media (max-width: 768px) {
    height: 140px !important;
  }
  
  @media (max-width: 480px) {
    height: 120px !important;
  }
}
</style> 