<template>
  <div class="chart-card">
    <div class="chart-header">
      <span class="chart-title">{{ t("completed_vs_cancelled") }}</span>
      <div class="dropdown-box">
        <select v-model="selectedPeriod" class="dropdown-select">
          <option value="7">{{ $t('last_7_days') }}</option>
          <option value="30">{{ $t('last30Days') }}</option>
          <option value="90">{{ $t('last3Months') }}</option>
        </select>
      </div>
    </div>
    <div class="chart-area">
      <Bar :data="chartData" :options="chartOptions" height="100%" />
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from "vue";
import { Bar } from "vue-chartjs";
import { useI18n } from "vue-i18n";

const { t } = useI18n();
import {
  Chart as ChartJS,
  Title,
  Legend,
  BarElement,
  CategoryScale,
  LinearScale,
} from "chart.js";

ChartJS.register(
  Title,
  Legend,
  BarElement,
  CategoryScale,
  LinearScale
);

const selectedPeriod = ref("7");

const days = [
  t("may18"), t("may19"), t("may20"), t("may21"), t("may22"), t("may23"), t("may24")
];
const completedOrders = [200, 150, 100, 130, 50, 150, 120];
const cancelledOrders = [100, 120, 110, 60, 200, 110, 100];

const completedColor = "#4B0A2B";
const cancelledColor = "#B0B0B0";

const chartData = computed(() => ({
  labels: days,
  datasets: [
    {
      label: t("completed"),
      backgroundColor: completedColor,
      data: completedOrders,
      borderRadius: 4,
      barPercentage: 0.7,
    },
    {
      label: t("cancelled"),
      backgroundColor: cancelledColor,
      data: cancelledOrders,
      borderRadius: 4,
      barPercentage: 0.7,
    },
  ],
}));

const chartOptions = ref({
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    legend: { display: false },
    datalabels: { display: false },
    tooltip: {
      backgroundColor: "rgba(255, 255, 255, 0.9)",
      titleColor: "#111827",
      bodyColor: "#111827",
      borderColor: "#E5E7EB",
      borderWidth: 1,
      padding: 10,
      cornerRadius: 4,
      displayColors: true,
      callbacks: {
        label: function (context) {
          return `${context.dataset.label}: ${context.raw}`;
        },
      },
    },
  },
  scales: {
    x: { grid: { display: false } },
    y: {
      beginAtZero: true,
      max: 200,
      grid: { color: "#F3F4F6" },
      ticks: { precision: 0 },
    },
  },
});
</script>

<style scoped>
.chart-card {
  background: #fff;
  border-radius: 18px;
  padding: 0.5rem 1.5rem 1.5rem 1.5rem;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  
  @media (max-width: 768px) {
    padding: 0.5rem 1rem 1rem 1rem;
  }
  
  @media (max-width: 480px) {
    padding: 0.5rem 0.75rem 0.75rem 0.75rem;
  }
}
.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
}
.chart-title {
  font-size: 1.15rem;
  font-weight: bold;
  color: #222;
  text-align: right;
}
.dropdown-box {
  position: relative;
}

.dropdown-select {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 24px;
  padding: 0.25rem 1.25rem 0.25rem 0.75rem;
  font-size: 1rem;
  color: #222;
  cursor: pointer;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6,9 12,15 18,9'%3e%3c/polyline%3e%3c/svg%3e");
  background-repeat: no-repeat;
  background-position: right 0.5rem center;
  background-size: 1rem;
  padding-right: 2rem;
}

.dropdown-select:hover {
  border-color: #d1d5db;
}

.dropdown-select:focus {
  border-color: #4B0A2B;
}
.chart-area {
  position: relative;
  height: 200px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  
  @media (max-width: 768px) {
    height: 140px;
    width: 300px;
  }
  
  @media (max-width: 480px) {
    height: 120px;
  }
}
.legend-container {
  display: flex;
  flex-direction: row;
  gap: 1.5rem;
  position: absolute;
  top: 0.5rem;
  right: 1.5rem;
  z-index: 2;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.legend-color {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: inline-block;
}
.legend-completed {
  background: #4B0A2B;
}
.legend-cancelled {
  background: #B0B0B0;
}
.legend-label {
  font-size: 1rem;
  font-weight: 600;
  color: #222;
}
</style> 