<script>
import { Pie } from "vue-chartjs";
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from "chart.js";
import ChartDataLabels from "chartjs-plugin-datalabels";

ChartJS.register(ArcElement, Tooltip, Legend, ChartDataLabels);

export default {
  name: "PaymentMethods",
  components: {
    Pie,
  },
  data() {
    return {
      paymentMethods: [
        { label: "حلويات", value: 15, color: "#5B183D" }, // dark maroon
        { label: "مشروبات", value: 15, color: "#191919" }, // black
        { label: "ساندوتشات", value: 30, color: "#D9D9D9" }, // light gray
        { label: "وجبات", value: 20, color: "#595959" }, // medium gray
      ],
      selectedPeriod: "30", // default
    };
  },
  computed: {
    chartData() {
      return {
        labels: this.paymentMethods.map((m) => m.label),
        datasets: [
          {
            data: this.paymentMethods.map((m) => m.value),
            backgroundColor: this.paymentMethods.map((m) => m.color),
            borderWidth: 4,
            borderColor: "#fff",
          },
        ],
      };
    },
    chartOptions() {
      return {
        responsive: true,
        plugins: {
          legend: { display: false },
          tooltip: { enabled: false },
          datalabels: {
            display: true,
            color: '#FFFFFF',
            margin:20,
            font: { weight: 'bold', size: 10  },
            formatter: (value) => value + '%',
       
            clamp: true,
            offset: 0,
            padding: 0,
            borderRadius: 0,
            clip: false,
          },
        },
        cutout: "0%",
      };
    },
  },
};
</script>

<template>
  <div class="payment-methods-container" dir="rtl">
    <div class="header-row">
      <h3 class="legend-title">أكثر أنواع الأطعمة المطلوبة</h3>
      <div class="dropdown-box">
        <select v-model="selectedPeriod" class="dropdown-select">
          <option value="30">آخر 30 يوم</option>
          <option value="7">آخر 7 أيام</option>
          <option value="90">آخر 90 يوم</option>
        </select>
      </div>
    </div>
    <div class="content-row">
      <div class="legend-section">
        <ul class="legend-list">
          <li v-for="(method, i) in paymentMethods" :key="i" class="legend-item">
            <span class="legend-color" :style="{ backgroundColor: method.color }"></span>
            {{ method.label }}
          </li>
        </ul>
      </div>
      <div class="pie-chart-section">
        <Pie :data="chartData" :options="chartOptions" />
      </div>
    </div>
  </div>
</template>

